### 5. SessionsController (passkey login)

```ruby
# app/controllers/sessions_controller.rb
class SessionsController < ApplicationController
  skip_before_action :authenticate_user!, only: [:new, :new_options, :create]
  before_action :require_no_user, only: [:new, :create]

  def new
    # Renders login page with passkey button
  end

  # Generates WebAuthn options for a usernameless passkey login
  def new_options
    options = WebAuthn::Credential.options_for_get(
      allow: :empty,
      user_verification: "preferred"
    )

    session[:login_challenge] = options.challenge
    render json: options
  rescue => e
    render json: { error: e.message }, status: :internal_server_error
  end

  # Verifies the passkey assertion and signs the user in
  def create
    webauthn_credential = WebAuthn::Credential.from_get(webauthn_get_params)

    credential = Credential.find_by(external_id: webauthn_credential.id)
    unless credential
      render json: { error: "No passkey found for this device" }, status: :unauthorized
      return
    end

    challenge = session.delete(:login_challenge)

    begin
      webauthn_credential.verify(
        challenge,
        public_key: credential.public_key,
        sign_count: credential.sign_count
      )
    rescue WebAuthn::Error => e
      render json: { error: e.message }, status: :unauthorized
      return
    end

    credential.update!(sign_count: webauthn_credential.sign_count)

    session[:user_id] = credential.user.id
    render json: { message: "Signed in successfully", user: credential.user.email }, status: :ok
  end

  def destroy
    session.delete(:user_id)
    redirect_to root_path, notice: "Signed out."
  end

  private

  def webauthn_get_params
    response = params[:response] || {}

    {
      id: params[:id],
      raw_id: params[:raw_id] || params[:rawId],
      type: params[:type],
      response: {
        authenticator_data: response[:authenticator_data] || response[:authenticatorData],
        client_data_json: response[:client_data_json] || response[:clientDataJSON],
        signature: response[:signature],
        user_handle: response[:user_handle] || response[:userHandle]
      }
    }
  end
end
```

