### 6. CredentialsController (passkey registration)

```ruby
# app/controllers/credentials_controller.rb
class CredentialsController < ApplicationController
  before_action :authenticate_user!

  def new
    # Renders passkey management page
  end

  # Generates options for creating a new passkey
  def options
    options = WebAuthn::Credential.options_for_create(
      user: {
        id: current_user.id.to_s,
        name: current_user.email,
        display_name: current_user.name.presence || current_user.email
      },
      exclude: current_user.credentials.pluck(:external_id)
    )

    session[:passkey_creation_challenge] = options.challenge
    render json: options
  rescue => e
    render json: { error: e.message }, status: :internal_server_error
  end

  # Verifies the passkey registration and stores it
  def create
    webauthn_credential = WebAuthn::Credential.from_create(webauthn_create_params)

    begin
      webauthn_credential.verify(session.delete(:passkey_creation_challenge))
    rescue WebAuthn::Error => e
      render json: { error: e.message }, status: :unprocessable_entity
      return
    end

    credential = current_user.credentials.create!(
      external_id: webauthn_credential.id,
      public_key: webauthn_credential.public_key,
      sign_count: webauthn_credential.sign_count,
      nickname: params[:nickname]
    )

    render json: { message: "Passkey registered", credential_id: credential.id }, status: :created
  rescue ActiveRecord::RecordInvalid => e
    render json: { error: e.message }, status: :unprocessable_entity
  end

  def destroy
    credential = current_user.credentials.find(params[:id])
    credential.destroy!
    redirect_to new_credential_path, notice: "Passkey removed."
  end

  private

  def webauthn_create_params
    response = params[:response] || {}

    {
      id: params[:id],
      raw_id: params[:raw_id] || params[:rawId],
      type: params[:type],
      response: {
        attestation_object: response[:attestation_object] || response[:attestationObject],
        client_data_json: response[:client_data_json] || response[:clientDataJSON]
      }
    }
  end
end
```

