### 7. Routes

```ruby
# config/routes.rb
Rails.application.routes.draw do
  root "home#index"

  # Session / login
  get "/login", to: "sessions#new", as: :login
  get "/login/options", to: "sessions#new_options", as: :login_options
  post "/login", to: "sessions#create", as: :session
  delete "/logout", to: "sessions#destroy", as: :logout

  # Passkey registration / management
  get "/settings/passkeys", to: "credentials#new", as: :new_credential
  get "/settings/passkeys/options", to: "credentials#options", as: :credential_options
  post "/settings/passkeys", to: "credentials#create", as: :credentials
  delete "/settings/passkeys/:id", to: "credentials#destroy", as: :credential
end
```

