#### Login page

```erb
<%# app/views/sessions/new.html.erb %>
<h1>Sign in with passkey</h1>
<button id="passkey-login">Sign in with passkey</button>
<p id="login-status"></p>

<script>
function base64urlToBuffer(base64url) {
  const base64 = base64url.replace(/-/g, '+').replace(/_/g, '/');
  const padding = '='.repeat((4 - (base64.length % 4)) % 4);
  const binary = atob(base64 + padding);
  const bytes = Uint8Array.from(binary, c => c.charCodeAt(0));
  return bytes.buffer;
}

function bufferToBase64url(buffer) {
  const bytes = new Uint8Array(buffer);
  let binary = '';
  bytes.forEach(b => binary += String.fromCharCode(b));
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

document.getElementById('passkey-login').addEventListener('click', async () => {
  const status = document.getElementById('login-status');
  status.textContent = 'Requesting passkey...';

  try {
    // 1. Get challenge from Rails
    const optionsResponse = await fetch('/login/options', {
      headers: { 'Accept': 'application/json' }
    });
    if (!optionsResponse.ok) throw new Error('Failed to start passkey login');
    const options = await optionsResponse.json();

    // 2. Convert base64url challenge and allowCredentials to ArrayBuffer
    options.challenge = base64urlToBuffer(options.challenge);
    if (options.allowCredentials) {
      options.allowCredentials.forEach(cred => {
        cred.id = base64urlToBuffer(cred.id);
      });
    }

    // 3. Ask browser for passkey assertion
    const credential = await navigator.credentials.get({ publicKey: options });

    // 4. Convert assertion to JSON for Rails
    const credentialJSON = {
      id: credential.id,
      raw_id: credential.id,
      type: credential.type,
      response: {
        client_data_json: bufferToBase64url(credential.response.clientDataJSON),
        authenticator_data: bufferToBase64url(credential.response.authenticatorData),
        signature: bufferToBase64url(credential.response.signature),
        user_handle: credential.response.userHandle ? bufferToBase64url(credential.response.userHandle) : null
      }
    };

    // 5. Verify assertion on the server
    const verifyResponse = await fetch('/login', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]').content
      },
      body: JSON.stringify(credentialJSON)
    });

    const data = await verifyResponse.json();
    if (!verifyResponse.ok) throw new Error(data.error || 'Login failed');

    window.location.href = '/';
  } catch (error) {
    status.textContent = error.message;
  }
});
</script>
```

#### Passkey management page

```erb
<%# app/views/credentials/new.html.erb %>
<h1>Manage passkeys</h1>

<h2>Register a new passkey</h2>
<button id="passkey-register">Register passkey</button>
<p id="register-status"></p>

<h2>Existing passkeys</h2>
<ul>
  <% current_user.credentials.each do |credential| %>
    <li>
      <%= credential.nickname.presence || credential.external_id %>
      <%= link_to "Remove", credential_path(credential), data: { turbo_method: :delete, turbo_confirm: "Remove this passkey?" } %>
    </li>
  <% end %>
</ul>

<script>
function base64urlToBuffer(base64url) {
  const base64 = base64url.replace(/-/g, '+').replace(/_/g, '/');
  const padding = '='.repeat((4 - (base64.length % 4)) % 4);
  const binary = atob(base64 + padding);
  const bytes = Uint8Array.from(binary, c => c.charCodeAt(0));
  return bytes.buffer;
}

function bufferToBase64url(buffer) {
  const bytes = new Uint8Array(buffer);
  let binary = '';
  bytes.forEach(b => binary += String.fromCharCode(b));
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

document.getElementById('passkey-register').addEventListener('click', async () => {
  const status = document.getElementById('register-status');
  status.textContent = 'Creating passkey...';

  try {
    // 1. Get creation options from Rails
    const optionsResponse = await fetch('/settings/passkeys/options', {
      headers: { 'Accept': 'application/json' }
    });
    if (!optionsResponse.ok) throw new Error('Failed to start passkey registration');
    const options = await optionsResponse.json();

    // 2. Convert base64url challenge, user.id and excludeCredentials to ArrayBuffer
    options.challenge = base64urlToBuffer(options.challenge);
    options.user.id = base64urlToBuffer(options.user.id);
    if (options.excludeCredentials) {
      options.excludeCredentials.forEach(cred => {
        cred.id = base64urlToBuffer(cred.id);
      });
    }

    // 3. Ask browser to create a passkey
    const credential = await navigator.credentials.create({ publicKey: options });

    // 4. Convert attestation to JSON for Rails
    const credentialJSON = {
      id: credential.id,
      raw_id: credential.id,
      type: credential.type,
      response: {
        client_data_json: bufferToBase64url(credential.response.clientDataJSON),
        attestation_object: bufferToBase64url(credential.response.attestationObject)
      }
    };

    // 5. Verify and store passkey on the server
    const verifyResponse = await fetch('/settings/passkeys', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]').content
      },
      body: JSON.stringify(credentialJSON)
    });

    const data = await verifyResponse.json();
    if (!verifyResponse.ok) throw new Error(data.error || 'Registration failed');

    status.textContent = 'Passkey registered!';
    window.location.reload();
  } catch (error) {
    status.textContent = error.message;
  }
});
</script>
```

---

### How it works

1. **Login**  
   - The browser requests `GET /login/options`. Rails generates a WebAuthn challenge and stores it in the session.  
   - The JavaScript decodes the challenge, calls `navigator.credentials.get()`, and posts the assertion to `POST /login`.  
   - Rails verifies the assertion using the stored challenge and the public key from the matching credential, then signs the user in.

2. **Registration**  
   - An authenticated user requests `GET /settings/passkeys/options`.  
   - Rails generates creation options, storing the challenge in the session.  
   - The browser creates a passkey and posts the attestation to `POST /settings/passkeys`.  
   - Rails verifies the attestation, stores the credential, and associates it with the user.

The code uses the `webauthn` gem to handle the cryptographic verification and challenge generation. The frontend JavaScript converts between base64url strings (used by Rails) and `ArrayBuffer` (required by the WebAuthn API).

Here's a complete Ruby implementation for accepting card payments with Adyen using Drop-in integration and verifying HMAC signatures:

## Gemfile

```ruby
source 'https://rubygems.org'

ruby '3.0.0'

gem 'sinatra', '~> 3.0'
gem 'sinatra-contrib', '~> 3.0'
gem 'adyen-ruby-api-library', '~> 8.0'
gem 'json', '~> 2.6'
gem 'dotenv', '~> 2.8'
