```ruby
# app/models/subscription.rb

class Subscription < ApplicationRecord
  belongs_to :user, optional: true

  validates :endpoint, presence: true, uniqueness: true
  validates :p256dh, presence: true
  validates :auth, presence: true

  scope :active, -> { where(active: true) }

  # Конвертація в формат для web-push гему
  def to_web_push_subscription
    {
      endpoint: endpoint,
      keys: {
        p256dh: p256dh,
        auth: auth
      }
    }
  end

  # Відправка push-сповіщення
  def send_notification(title:, body:, url: nil, icon: nil, badge: nil)
    payload = build_payload(title: title, body: body, url: url, icon: icon, badge: badge)

    begin
      WebPush.payload_send(
        message: payload.to_json,
        endpoint: endpoint,
        p256dh: p256dh,
        auth: auth,
        ttl: 24 * 60 * 60,
        vapid: {
          subject: ENV['VAPID_SUBJECT'],
          public_key: ENV['VAPID_PUBLIC_KEY'],
          private_key: ENV['VAPID_PRIVATE_KEY']
        }
      )

      update(last_sent_at: Time.current)
      true
    rescue WebPush::InvalidSubscription => e
      # Підписка недійсна - деактивуємо
      update(active: false)
      Rails.logger.warn("Invalid subscription #{id}: #{e.message}")
      false
    rescue WebPush::ExpiredSubscription => e
      # Підписка закінчилась - видаляємо
      destroy
      Rails.logger.warn("Expired subscription #{id}: #{e.message}")
      false
    rescue StandardError => e
      Rails.logger.error("Failed to send push notification: #{e.message}")
      false
    end
  end

  private

  def build_payload(title:, body:, url:, icon:, badge:)
    {
      title: title,
      body: body,
      icon: icon || '/icon-192x192.png',
      badge: badge || '/badge-72x72.png',
      data: {
        url: url || '/',
        timestamp: Time.current.to_i
      },
      actions: [
        {
          action: 'open',
          title: 'Відкрити'
        },
        {
          action: 'close',
          title: 'Закрити'
        }
      ]
    }
  end
end
