# app/controllers/api/subscriptions_controller.rb

module Api
  class SubscriptionsController < ApplicationController
    before_action :authenticate_user!

    # POST /api/subscriptions
    def create
      subscription = current_user.subscriptions.find_or_initialize_by(
        endpoint: subscription_params[:endpoint]
      )

      subscription.assign_attributes(
        p256dh: subscription_params[:keys][:p256dh],
        auth: subscription_params[:keys][:auth],
        user_agent: request.user_agent,
        platform: detect_platform(request.user_agent),
        active: true
      )

      if subscription.save
        render json: { success: true, subscription_id: subscription.id }, status: :created
      else
        render json: { success: false, errors: subscription.errors.full_messages }, status: :unprocessable_entity
      end
    end

    # DELETE /api/subscriptions/:id
    def destroy
      subscription = current_user.subscriptions.find(params[:id])
      subscription.destroy

      render json: { success: true }, status: :ok
    end

    # PATCH /api/subscriptions/:id/toggle
    def toggle
      subscription = current_user.subscriptions.find(params[:id])
      subscription.update(active: !subscription.active)

      render json: { success: true, active: subscription.active }, status: :ok
    end

    private

    def subscription_params
      params.require(:subscription).permit(
        :endpoint,
        keys: [:p256dh, :auth]
      )
    end

    def detect_platform(user_agent)
      case user_agent
      when /Windows/i then 'windows'
      when /Macintosh/i then 'macos'
      when /Linux/i then 'linux'
      when /Android/i then 'android'
      when /iPhone|iPad|iPod/i then 'ios'
      else 'unknown'
      end
    end
  end
end
