## JavaScript для клієнта

### app/javascript/packs/push_notifications.js

```javascript
// app/javascript/packs/push_notifications.js

class PushNotificationManager {
  constructor() {
    this.publicKey = process.env.VAPID_PUBLIC_KEY;
    this.swRegistration = null;
    this.isSubscribed = false;
  }

  async initialize() {
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
      console.warn('Push notifications are not supported');
      return false;
    }

    try {
      // Реєстрація service worker
      this.swRegistration = await navigator.serviceWorker.register('/service-worker.js');

      // Перевірка наявності підписки
      this.isSubscribed = !!(await this.swRegistration.pushManager.getSubscription());

      return true;
    } catch (error) {
      console.error('Service Worker registration failed:', error);
      return false;
    }
  }

  async requestPermission() {
    try {
      const permission = await Notification.requestPermission();
      return permission === 'granted';
    } catch (error) {
      console.error('Permission request failed:', error);
      return false;
    }
  }

  async subscribe() {
    if (!this.swRegistration) {
      throw new Error('Service Worker is not registered');
    }

    try {
      const subscription = await this.swRegistration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: this.urlBase64ToUint8Array(this.publicKey)
      });

      // Відправка підписки на сервер
      await this.sendSubscriptionToServer(subscription);
      this.isSubscribed = true;

      return subscription;
    } catch (error) {
      console.error('Failed to subscribe:', error);
      throw error;
    }
  }

  async unsubscribe() {
    if (!this.swRegistration) {
      return;
    }

    try {
      const subscription = await this.swRegistration.pushManager.getSubscription();
      if (subscription) {
        await subscription.unsubscribe();
        await this.deleteSubscriptionFromServer(subscription);
        this.isSubscribed = false;
      }
    } catch (error) {
      console.error('Failed to unsubscribe:', error);
    }
  }

  async sendSubscriptionToServer(subscription) {
    const response = await fetch('/api/subscriptions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': document.querySelector('[name="csrf-token"]').content
      },
      body: JSON.stringify(subscription)
    });

    if (!response.ok) {
      throw new Error('Failed to save subscription');
    }
  }

  async deleteSubscriptionFromServer(subscription) {
    const response = await fetch(`/api/subscriptions/${subscription.id}`, {
      method: 'DELETE',
      headers: {
        'X-CSRF-Token': document.querySelector('[name="csrf-token"]').content
      }
    });

    if (!response.ok) {
      throw new Error('Failed to delete subscription');
    }
  }

  urlBase64ToUint8Array(base64String) {
    const padding = '='.repeat((4 - base64String.length % 4) % 4);
    const base64 = (base64String + padding)
      .replace(/\-/g, '+')
      .replace(/_/g, '/');

    const rawData = window.atob(base64);
    const outputArray = new Uint8Array(rawData.length);

    for (let i = 0; i < rawData.length; ++i) {
      outputArray[i] = rawData.charCodeAt(i);
    }

    return outputArray;
  }
}

// Експорт для використання в інших частинах застосунку
export default PushNotificationManager;
```

