NOVA_POSHTA_URL = "https://api.novaposhta.ua/v2.0/json/"
NOMINATIM_URL   = "https://nominatim.openstreetmap.org"

# Warehouse type refs for parcel lockers.
POSHTOMAT_TYPE_REFS = [
  "f9316480-5f2d-425d-bc2c-ac7cd29decf0", # Поштомат (Nova Poshta)
  "95dc212d-479c-4ffb-a8ab-8c1b9073d0bc"  # Поштомат ПриватБанку
].freeze

class GeocodingError < StandardError; end
class NovaPoshtaError < StandardError; end

# Simple in-memory TTL cache
class TtlCache
  def initialize(ttl)
    @ttl = ttl
    @store = {}
    @mutex = Mutex.new
  end

  def fetch(key)
    @mutex.synchronize do
      entry = @store[key]
      return entry[:value] if entry && entry[:expires] > Time.now
    end
    value = yield
    @mutex.synchronize { @store[key] = { value: value, expires: Time.now + @ttl } }
    value
  end
end

module Geo
  EARTH_RADIUS_KM = 6371.0088

  def self.distance_km(lat1, lon1, lat2, lon2)
    rad = Math::PI / 180
    dlat = (lat2 - lat1) * rad
    dlon = (lon2 - lon1) * rad
    a = Math.sin(dlat / 2)**2 +
        Math.cos(lat1 * rad) * Math.cos(lat2 * rad) * Math.sin(dlon / 2)**2
    2 * EARTH_RADIUS_KM * Math.asin(Math.sqrt(a))
  end
end

class Geocoder
  CACHE = TtlCache.new(24 * 3600)

  def initialize(contact: ENV.fetch("CONTACT_EMAIL", "unknown@example.com"))
    @conn = Faraday.new(url: NOMINATIM_URL, request: { timeout: 10, open_timeout: 5 }) do |f|
      f.headers["User-Agent"] = "poshtomat-finder/1.0 (#{contact})"
    end
  end

  # Returns { lat:, lon:, city:, display_name: }
  def geocode(address)
    key = address.strip.downcase
    CACHE.fetch(key) { request(address) }
  end

  private

  def request(address)
    resp = @conn.get("/search", {
      q: address, format: "jsonv2", limit: 1, addressdetails: 1,
      countrycodes: "ua", "accept-language": "uk"
    })
    raise GeocodingError, "Geocoding service returned HTTP #{resp.status}" unless resp.success?

    result = JSON.parse(resp.body).first
    raise GeocodingError, "Address not found: #{address}" unless result

    addr = result["address"] || {}
    city = addr["city"] || addr["town"] || addr["village"] || addr["municipality"]
    raise GeocodingError, "Could not determine the city for that address" unless city

    {
      lat: result["lat"].to_f,
      lon: result["lon"].to_f,
      city: city,
      display_name: result["display_name"]
    }
  rescue Faraday::Error => e
    raise GeocodingError, "Geocoding failed: #{e.message}"
  end
end

class NovaPoshta
  PAGE_SIZE = 500
  CACHE = TtlCache.new(3600)

  def initialize(api_key)
    @api_key = api_key
    @conn = Faraday.new(url: NOVA_POSHTA_URL, request: { timeout: 30, open_timeout: 5 }) do |f|
      f.headers["Content-Type"] = "application/json"
    end
  end

  # All poshtomats in a city that have coordinates.
  def poshtomats_in_city(city)
    CACHE.fetch(city.downcase) do
      POSHTOMAT_TYPE_REFS.flat_map { |ref| fetch_all(city, ref) }
                         .uniq { |w| w[:ref] }
    end
  end

  private

  def fetch_all(city, type_ref)
    results = []
    page = 1
    loop do
      batch = call(
        "Address", "getWarehouses",
        "CityName" => city,
        "TypeOfWarehouseRef" => type_ref,
        "Limit" => PAGE_SIZE.to_s,
        "Page" => page.to_s
      )
      results.concat(batch.filter_map { |w| normalize(w) })
      break if batch.size < PAGE_SIZE || page >= 20

      page += 1
    end
    results
  end

  def normalize(w)
    lat = w["Latitude"].to_f
    lon = w["Longitude"].to_f
    return nil if lat.zero? || lon.zero?

    {
      ref: w["Ref"],
      number: w["Number"],
      name: w["Description"],
      address: w["ShortAddress"] || w["Description"],
      city: w["CityDescription"],
      lat: lat,
      lon: lon,
      max_weight: w["PlaceMaxWeightAllowed"],
      schedule: (w["Schedule"] || {}).slice(
        "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"
      )
    }
  end

  def call(model, method, props)
    body = { apiKey: @api_key, modelName: model, calledMethod: method, methodProperties: props }
    resp = @conn.post("", JSON.generate(body))
    raise NovaPoshtaError, "Nova Poshta returned HTTP #{resp.status}" unless resp.success?

    data = JSON.parse(resp.body)
    unless data["success"]
      msg = Array(data["errors"]).join("; ")
      raise NovaPoshtaError, "Nova Poshta API error: #{msg.empty? ? 'unknown' : msg}"
    end
    data["data"]
  rescue Faraday::Error, JSON::ParserError => e
    raise NovaPoshtaError, "Nova Poshta request failed: #{e.message}"
  end
end

helpers do
  def h(text)
    Rack::Utils.escape_html(text.to_s)
  end

  # Safe for embedding inside a <script> tag
  def json_for_script(obj)
    JSON.generate(obj).gsub("<", "\\u003c").gsub(">", "\\u003e").gsub("&", "\\u0026")
  end
end

get "/" do
  @address = params["address"].to_s.strip
  @radius  = (params["radius"] || 2).to_f.clamp(0.1, 20)
  @limit   = (params["limit"] || 20).to_i.clamp(1, 100)
  @error   = nil
  @origin  = nil
  @lockers = []

  unless @address.empty?
    begin
      api_key = ENV["NOVA_POSHTA_API_KEY"]
      raise NovaPoshtaError, "NOVA_POSHTA_API_KEY environment variable is not set" if api_key.to_s.empty?

      @origin = Geocoder.new.geocode(@address)
      all = NovaPoshta.new(api_key).poshtomats_in_city(@origin[:city])

      @lockers = all
        .map { |w| w.merge(distance_km: Geo.distance_km(@origin[:lat], @origin[:lon], w[:lat], w[:lon])) }
        .select { |w| w[:distance_km] <= @radius }
        .sort_by { |w| w[:distance_km] }
        .first(@limit)
    rescue GeocodingError, NovaPoshtaError => e
      @error = e.message
    end
  end

  erb :index
end

__END__

