    const days = { Monday: "Пн", Tuesday: "Вт", Wednesday: "Ср", Thursday: "Чт",
                   Friday: "Пт", Saturday: "Сб", Sunday: "Нд" };

    const map = L.map("map").setView(origin ? [origin.lat, origin.lon] : [48.38, 31.17], origin ? 15 : 6);
    L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png", {
      maxZoom: 19,
      attribution: "&copy; OpenStreetMap contributors"
    }).addTo(map);

    function el(tag, text, style) {
      const e = document.createElement(tag);
      if (text !== undefined) e.textContent = text;
      if (style) e.style.cssText = style;
      return e;
    }

    function popupFor(l) {
      const box = el("div");
      box.appendChild(el("strong", l.name));
      box.appendChild(el("div", (l.distance_km * 1000).toFixed(0) + " м від вказаної адреси"));
      if (l.max_weight) box.appendChild(el("div", "Макс. вага: " + l.max_weight + " кг"));
      const sched = el("div", undefined, "margin-top:4px;font-size:12px");
      Object.entries(l.schedule || {}).forEach(([d, t]) => sched.appendChild(el("div", (days[d] || d) + ": " + t)));
      box.appendChild(sched);
      const route = el("a", "Маршрут");
      route.href = "https://www.google.com/maps/dir/?api=1&destination=" + l.lat + "," + l.lon;
      route.target = "_blank";
      route.rel = "noopener";
      box.appendChild(route);
      return box;
    }

    const bounds = [];

    if (origin) {
      L.circleMarker([origin.lat, origin.lon], { radius: 9, color: "#1a5fb4", fillColor: "#3584e4", fillOpacity: 0.9 })
        .addTo(map).bindPopup("Ваша адреса");
      bounds.push([origin.lat, origin.lon]);
    }

    const list = document.getElementById("list");
    lockers.forEach(l => {
      const marker = L.marker([l.lat, l.lon]).addTo(map).bindPopup(popupFor(l));
      bounds.push([l.lat, l.lon]);

      const row = el("div");
      row.appendChild(el("strong", l.name));
      row.appendChild(el("div", (l.distance_km * 1000).toFixed(0) + " м", "color:#666"));
      row.addEventListener("click", () => { map.setView([l.lat, l.lon], 17); marker.openPopup(); });
      list.appendChild(row);
    });

    if (bounds.length > 1) map.fitBounds(bounds, { padding: [30, 30] });
  </script>
</body>
</html>
```

## Notes

- **API key:** Get a free key from your Nova Poshta business account and set `NOVA_POSHTA_API_KEY`.
- **How it works:**
  1. The address is geocoded with OpenStreetMap Nominatim, which also returns the city name.
  2. All lockers in that city are loaded from Nova Poshta `Address/getWarehouses`. The code paginates and caches results for an hour.
  3. Distances are computed with the haversine formula, and the nearest ones within the chosen radius are shown on a Leaflet map and in a side list.
- **Limitations:** Only lockers in the geocoded city are searched, because the API has no geo query. An address near a city border may therefore miss lockers on the other side.
- **Nominatim policy:** Nominatim allows about one request per second and requires an identifying User-Agent. Set `CONTACT_EMAIL`, and use your own geocoder for heavy traffic.
- **Safety:** API data is inserted into the page with `textContent` and JSON is escaped for the script tag, so the page isn't open to XSS.

