### app.rb

```ruby
require 'sinatra'
require 'sinatra/reloader' if development?
require 'ibanizator'
require 'dry-validation'
require 'json'

# Custom validation classes
class BankValidator
  class IBANValidator
    def self.validate(iban)
      iban = iban.to_s.gsub(/\s+/, '').upcase

      return { valid: false, error: "IBAN is required" } if iban.empty?

      # Check basic format
      unless iban.match?(/^[A-Z]{2}\d{2}[A-Z0-9]{11,30}$/)
        return { valid: false, error: "Invalid IBAN format. Should start with 2 letters followed by 2 digits" }
      end

      # Validate using ibanizator gem
      begin
        iban_obj = Ibanizator.iban_from_string(iban)

        if iban_obj.valid?
          { valid: true, formatted: format_iban(iban), bank_code: iban_obj.bank_code, 
            account_number: iban_obj.account_number, country_code: iban_obj.country_code }
        else
          { valid: false, error: "Invalid IBAN checksum" }
        end
      rescue => e
        { valid: false, error: "Invalid IBAN: #{e.message}" }
      end
    end

    private

    def self.format_iban(iban)
      iban.scan(/.{1,4}/).join(' ')
    end
  end

  class BICValidator
    def self.validate(bic)
      bic = bic.to_s.gsub(/\s+/, '').upcase

      return { valid: false, error: "BIC is required" } if bic.empty?

      # BIC format: 4 letters (bank code) + 2 letters (country) + 2 alphanumeric (location) + optional 3 alphanumeric (branch)
      unless bic.match?(/^[A-Z]{4}[A-Z]{2}[A-Z0-9]{2}([A-Z0-9]{3})?$/)
        return { valid: false, error: "Invalid BIC format. Should be 8 or 11 characters (e.g., DEUTDEFF or DEUTDEFF500)" }
      end

      # Additional validation - check country code
      country_code = bic[4, 2]
      valid_countries = ['DE', 'AT', 'CH', 'FR', 'GB', 'US', 'NL', 'BE', 'ES', 'IT', 'PL', 'SE', 'NO', 'DK', 'FI']

      unless valid_countries.include?(country_code)
        return { valid: false, error: "Invalid country code in BIC: #{country_code}" }
      end

      { valid: true, formatted: bic, bank_code: bic[0, 4], country_code: country_code, 
        location_code: bic[6, 2], branch_code: bic.length > 8 ? bic[8, 3] : nil }
    end
  end
end

# Form validation schema
class BankFormSchema < Dry::Validation::Contract
  params do
    required(:iban).filled(:string)
    required(:bic).filled(:string)
    optional(:account_holder).maybe(:string)
  end
end

# Sinatra application
class BankValidationApp < Sinatra::Base
  configure :development do
    register Sinatra::Reloader
  end

  configure do
    set :server, :puma
    set :public_folder, File.dirname(__FILE__) + '/public'
    set :views, File.dirname(__FILE__) + '/views'
  end

  get '/' do
    erb :index, locals: { 
      errors: {}, 
      form_data: { iban: '', bic: '', account_holder: '' },
      validation_results: nil
    }
  end

  post '/validate' do
    content_type :json

    form_data = {
      iban: params[:iban].to_s.strip,
      bic: params[:bic].to_s.strip,
      account_holder: params[:account_holder].to_s.strip
    }

    # Validate form presence
    schema = BankFormSchema.new
    form_validation = schema.call(form_data)

    if form_validation.failure?
      return {
        success: false,
        errors: form_validation.errors.to_h.transform_values { |v| v.join(', ') }
      }.to_json
    end

    # Validate IBAN and BIC
    iban_result = BankValidator::IBANValidator.validate(form_data[:iban])
    bic_result = BankValidator::BICValidator.validate(form_data[:bic])

    errors = {}
    errors[:iban] = iban_result[:error] unless iban_result[:valid]
    errors[:bic] = bic_result[:error] unless bic_result[:valid]

    if errors.empty?
      {
        success: true,
        message: "IBAN and BIC are valid!",
        data: {
          iban: iban_result,
          bic: bic_result,
          combined: {
            iban: iban_result[:formatted],
            bic: bic_result[:formatted],
            account_holder: form_data[:account_holder]
          }
        }
      }.to_json
    else
      {
        success: false,
        errors: errors
      }.to_json
    end
  end

  not_found do
    status 404
    "Page not found"
  end

  run! if app_file == $0
end
```

