## 4. Сервіс відправлення

```ruby
# app/services/web_push_sender.rb
require "web-push"

class WebPushSender
  # Повертає true, якщо сповіщення прийнято push-сервісом
  def self.call(subscription, title:, body:, url: "/", icon: nil, tag: nil, ttl: 12 * 60 * 60, urgency: "normal")
    new(subscription).deliver(
      { title: title, body: body, url: url, icon: icon, tag: tag }.compact,
      ttl: ttl,
      urgency: urgency
    )
  end

  def initialize(subscription)
    @subscription = subscription
  end

  def deliver(payload, ttl:, urgency:)
    WebPush.payload_send(
      message: payload.to_json,
      endpoint: @subscription.endpoint,
      p256dh: @subscription.p256dh_key,
      auth: @subscription.auth_key,
      vapid: VapidConfig.to_h,
      ttl: ttl,
      urgency: urgency,       # very-low | low | normal | high
      open_timeout: 5,
      read_timeout: 5
    )
    true
  rescue WebPush::ExpiredSubscription, WebPush::InvalidSubscription
    # Підписка більше недійсна (користувач відписався / браузер видалив її)
    Rails.logger.info("[WebPush] Видаляємо недійсну підписку ##{@subscription.id}")
    @subscription.destroy
    false
  rescue WebPush::Unauthorized => e
    Rails.logger.error("[WebPush] Помилка VAPID-автентифікації: #{e.message}")
    false
  rescue WebPush::PayloadTooLarge => e
    Rails.logger.error("[WebPush] Занадто великий payload: #{e.message}")
    false
  rescue WebPush::TooManyRequests => e
    Rails.logger.warn("[WebPush] Ліміт запитів: #{e.message}")
    raise # нехай job повторить спробу пізніше
  rescue WebPush::ResponseError, Net::OpenTimeout, Net::ReadTimeout, SocketError => e
    Rails.logger.error("[WebPush] Помилка відправлення: #{e.class}: #{e.message}")
    false
  end
end
```

## 5. Фонове завдання

```ruby
# app/jobs/send_push_notification_job.rb
class SendPushNotificationJob < ApplicationJob
  queue_as :default

  retry_on WebPush::TooManyRequests, wait: 1.minute, attempts: 5

  def perform(user_id, title:, body:, url: "/")
    user = User.find_by(id: user_id)
    return unless user

    user.push_subscriptions.find_each do |subscription|
      WebPushSender.call(subscription, title: title, body: body, url: url)
    end
  end
end
```

