## 7. Service Worker

```javascript
// public/service-worker.js
self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (event) => event.waitUntil(self.clients.claim()));

self.addEventListener("push", (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch (_) {
    data = { title: "Сповіщення", body: event.data && event.data.text() };
  }

  const title = data.title || "Сповіщення";
  const options = {
    body: data.body,
    icon: data.icon || "/icon.png",
    tag: data.tag,
    data: { url: data.url || "/" }
  };

  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const url = (event.notification.data && event.notification.data.url) || "/";

  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clients) => {
      for (const client of clients) {
        if (client.url.includes(url) && "focus" in client) return client.focus();
      }
      return self.clients.openWindow(url);
    })
  );
});
```

## 8. Клієнтський JavaScript

```javascript
// app/javascript/push_notifications.js
const csrfToken = () => document.querySelector("meta[name='csrf-token']")?.content;

function urlBase64ToUint8Array(base64String) {
  const padding = "=".repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
  const raw = atob(base64);
  return Uint8Array.from([...raw].map((c) => c.charCodeAt(0)));
}

async function postJSON(url, body, method = "POST") {
  return fetch(url, {
    method,
    headers: {
      "Content-Type": "application/json",
      "Accept": "application/json",
      "X-CSRF-Token": csrfToken()
    },
    body: body ? JSON.stringify(body) : undefined,
    credentials: "same-origin"
  });
}

export function pushSupported() {
  return "serviceWorker" in navigator && "PushManager" in window && "Notification" in window;
}

export async function subscribeToPush() {
  if (!pushSupported()) throw new Error("Браузер не підтримує Web Push");

  const permission = await Notification.requestPermission();
  if (permission !== "granted") throw new Error("Дозвіл на сповіщення не надано");

  const registration = await navigator.serviceWorker.register("/service-worker.js");
  await navigator.serviceWorker.ready;

  const { public_key } = await (await fetch("/vapid_public_key")).json();

  let subscription = await registration.pushManager.getSubscription();
  if (!subscription) {
    subscription = await registration.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToUint8Array(public_key)
    });
  }

  const response = await postJSON("/push_subscriptions", { subscription: subscription.toJSON() });
  if (!response.ok) throw new Error("Не вдалося зберегти підписку на сервері");
  return subscription;
}

export async function unsubscribeFromPush() {
  const registration = await navigator.serviceWorker.getRegistration();
  const subscription = await registration?.pushManager.getSubscription();
  if (!subscription) return;

  await postJSON("/push_subscriptions", { endpoint: subscription.endpoint }, "DELETE");
  await subscription.unsubscribe();
}
